sp_css.css:
/* ===== AEGIS Careers — Shared Design Tokens ===== */

@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

:root{
  --forest-900:#0F241C;
  --forest-800:#173A2C;
  --forest-700:#20503C;
  --forest-600:#2C6A4F;

  --cream:#F4EFE3;
  --cream-2:#ECE4D2;
  --paper:#FFFFFF;

  --terracotta:#E2694B;
  --terracotta-dark:#C6543A;

  --mustard:#E7A83C;
  --mustard-dark:#CC8F28;

  --ink:#1E241F;
  --ink-soft:#5C6459;
  --line:#DED5BE;

  --radius-lg:28px;
  --radius-md:18px;
  --radius-sm:10px;

  --shadow-card:0 10px 30px -12px rgba(15,36,28,0.18);

  /* ServiceNow Theme Variables */
  --now-color--primary-1:var(--forest-900);
  --now-color--primary-2:var(--forest-800);
  --now-color--secondary-1:var(--terracotta);
  --now-color--secondary-2:var(--terracotta-dark);
}

/* ===== Global ===== */

body{
  background:var(--cream);
  color:var(--ink);
  font-family:'Inter',system-ui,-apple-system,sans-serif;
}

/* ===== Headings ===== */

h1,h2,h3,h4,h5,h6,
.aegis-h{
  font-family:'Poppins',sans-serif;
  color:var(--forest-900);
}

/* ===== Cards ===== */

.card,
.now-card,
.sn-card{
  background:var(--paper);
  border-radius:var(--radius-md);
  box-shadow:var(--shadow-card);
}

/* ===== Links ===== */

a{
  color:var(--forest-700);
}

a:hover{
  color:var(--terracotta);
}

/* ===== Primary Button ===== */

.aegis-btn-primary,
button.btn-primary{
  background:var(--terracotta);
  color:#fff;
  border:none;
  border-radius:999px;
  padding:12px 22px;
  font-weight:600;
  cursor:pointer;
}

.aegis-btn-primary:hover,
button.btn-primary:hover{
  background:var(--terracotta-dark);
}

/* ===== Dark Button ===== */

.aegis-btn-dark{
  background:var(--forest-900);
  color:#fff;
  border:none;
  border-radius:999px;
  padding:13px 24px;
  font-weight:600;
}

.aegis-btn-dark:hover{
  background:var(--forest-800);
}

/* ===== Outline Button ===== */

.aegis-btn-outline{
  background:transparent;
  color:var(--forest-900);
  border:1.5px solid var(--forest-900);
  border-radius:999px;
  padding:11px 22px;
  font-weight:600;
}

.aegis-btn-outline:hover{
  background:var(--forest-900);
  color:#fff;
}

/* ===== Inputs ===== */

input,
textarea,
select{
  border:1px solid var(--line);
  border-radius:var(--radius-sm);
}

input:focus,
textarea:focus,
select:focus{
  outline:none;
  border-color:var(--forest-600);
}

/* ===== Navbar/Header ===== */

header,
.navbar,
.now-global-header{
  background:var(--forest-900);
  color:white;
}

/* ===== Footer ===== */

footer{
  background:var(--forest-900);
  color:white;
}
